'use strict';
// Newest release first. Update this list and asset version URLs with every release.
const RELEASES=[{"version": "1.4.8", "date": "2026-10-12", "title": "Geburtsnamen und ruhiger Stammbaum", "changes": ["Gespeicherte Geburtsnamen erscheinen direkt auf Stammbaumkarten und Personenlisten, unabhängig vom Geburtsort.", "Eltern-Kind-Verbindungen werden ohne Pfeilspitzen dargestellt; Belegstatus und Familienzweige bleiben erhalten.", "Geburtsnamen können als Ergänzung zur Admin-Freigabe eingereicht werden und erscheinen auch in freigegebenen Leseansichten."]},{"version": "1.4.7", "date": "2026-10-09", "title": "Einladungsmails lesbar anzeigen", "changes": ["Einladungsmails enthalten eine Text- und HTML-Version mit anklickbarem Einladungsbutton.", "UTF-8-Inhalte werden für den Mailtransport Base64-kodiert; MIME-Struktur und Zeilenumbrüche vereinheitlicht.", "Mailtests prüfen beide dekodierten Nachrichtenteile und den vollständigen Einladungslink."]},{"version": "1.4.6", "date": "2026-10-09", "title": "Benutzer anlegen und einladen", "changes": ["Admins können aktive Mitglieder oder weitere Admins direkt anlegen.", "Einladung per E-Mail mit einmaligem Link, eigenem Passwort und sieben Tagen Gültigkeit.", "Offene Einladungen anzeigen und widerrufen; Versandprobleme werden mit kopierbarem Link angezeigt."]},{"version": "1.4.5", "date": "2026-10-09", "title": "Familienzweige statt Liniengewirr", "changes": ["Eltern mit identischer Zuordnung werden in einem gemeinsamen Familienzweig mit Kinderlinie zusammengefasst.", "Geschwister und ihre Partner werden nach ihrer Herkunft angeordnet, statt alphabetisch über die ganze Generation verteilt.", "Ein Pfeil pro Kind und mehr Abstand zwischen Generationen machen große Familien besser lesbar.", "Unterschiedliche Elternpaare und unterschiedliche Belegstände erhalten getrennte Zweige."]},{"version": "1.4.4", "date": "2026-10-09", "title": "Eindeutige Stammbaumlinien", "changes": ["Grüne Eltern-Kind-Verbindungen erhalten Pfeilspitzen am tatsächlichen Kind und getrennte Anschlusspunkte.", "Linien über mehrere Generationen werden außen geführt, damit sie keine fremden Personenkarten durchlaufen.", "Partnerlinien verbinden die Kartenränder; weiter entfernte Partner werden oberhalb ihrer Karten verbunden.", "Belegstatus und gespeicherte Familienverbindungen bleiben unverändert."]},{"version": "1.4.3", "date": "2026-10-09", "title": "Anmeldung ohne Zugangsdaten im Link", "changes": ["Anmeldung, Registrierung und Einrichtung verwenden ausdrücklich POST, auch wenn JavaScript ausfällt.", "Zugangsdaten aus alten URL-Parametern werden entfernt; Loginfelder werden nicht durch die App vorbelegt.", "Unter Mein Konto kann das eigene Passwort geändert werden; alle bisherigen Sitzungen dieses Kontos werden dabei widerrufen."]},{"version": "1.4.2", "date": "2026-10-09", "title": "Vorlage übernehmen und zügig bestätigen", "changes": ["Eindeutige Elternschaft sowie Ehen und Partnerschaften aus der ursprünglichen PDF werden beim nächsten Öffnen als Admin automatisch als belegt übernommen.", "Ausdrücklich fragliche, individuell bewertete und zur Prüfung eingereichte Verbindungen bleiben ausgenommen.", "Einzelbestätigungen bleiben auf der Personenseite; rote Felder zeigen die wartende Freigabe.", "Nach Freigabe verschwindet das Bestätigungsfeld; offene Anträge verhindern doppelte Einreichungen."]},{"version": "1.4.1", "date": "2026-10-09", "title": "Prüfliste aufräumen", "changes": ["Die Prüfliste zeigt nur noch offene Vorschläge.", "Freigegebene und abgelehnte Fälle verschwinden nach Freigabe oder Aktualisieren aus der Prüfliste; gespeicherte Vorschläge und Änderungsverlauf bleiben erhalten."]},{"version": "1.4.0", "date": "2026-10-09", "title": "Familienverbindungen prüfen", "changes": ["Belegstatus bestehender Eltern-Kind-Verbindungen und Partnerschaften direkt bei der Person prüfen.", "Belegt oder ausdrücklich ungeklärt mit Quelle einreichen; Übernahme erst nach Admin-Freigabe.", "Sammelprüfung eindeutiger Elternschaft aus der ursprünglichen Vorlage; sieben ausdrücklich fragliche Verbindungen bleiben ausgenommen.", "Unbekannte Namen und biologische Einordnung werden getrennt vom Belegstatus geführt."]},{"version":"1.3.2","date":"2026-10-09","title":"Belegte Familienverbindungen","changes":["Durchgezogene Linien kennzeichnen belegte Elternschaft unabhängig von der biologischen Einordnung.","Die vier ausdrücklich bestätigten Verbindungen in der direkten Familienlinie können unter Benutzer zur Freigabe eingereicht werden.","Andere ungeklärte Verbindungen bleiben gestrichelt; Änderungen werden protokolliert."]},{"version":"1.3.1","date":"2026-10-09","title":"Porträtzuordnungen korrigieren","changes":["Korrektur dreier vertauschter Porträtzuordnungen aus dem Erstimport vorbereitet.","Admins können die Korrektur unter Benutzer zur Prüfung anlegen und mit Bildvorschau in der Prüfliste freigeben.","Personenanhänge und Bildzuordnungen werden gemeinsam korrigiert; zwischenzeitliche Änderungen verhindern die Übernahme."]},{"version":"1.3.0","date":"2026-10-09","title":"Version & Patch-Historie","changes":["Versionshinweis auf der Anmeldeseite, im Archiv und in der Leseansicht.","Klick auf die Version öffnet die Patch-Historie mit Datum und Änderungen.","Versionsanzeige bleibt auch am Handy sichtbar.","Neue Versionsnummern in den Dateiadressen sorgen dafür, dass der Browser aktualisierte Dateien lädt."]},{"version":"1.2.0","date":"2026-10-09","title":"Neue Familienlinien importieren","changes":["JSON- und GEDCOM-Import mit bearbeitbarem JSON-Entwurf und Personenzuordnung.","Mögliche Dubletten und widersprüchliche Angaben werden zur Prüfung angezeigt.","Neue Linien werden erst nach Admin-Freigabe gemeinsam übernommen; Fehler verhindern die gesamte Übernahme.","Originaldateien bleiben als Quellen erhalten.","Optionale PDF-/PNG-/JPG-Erkennung über OpenAI: eigener API-Schlüssel und ausdrückliche Übertragungsbestätigung erforderlich."]},{"version":"1.1.0","date":"2026-10-09","title":"Bilder direkt im Archiv ansehen","changes":["Personenbilder öffnen in einem Popup auf derselben Seite.","Sanfte Vergrößerung beim Öffnen; Bildklick schaltet die Originalgröße ein oder aus.","Schließen per Escape, Schließen-Taste oder Klick neben das Popup."]},{"version":"1.0.0","date":"2026-10-09","title":"PHP-Version für netcup","changes":["Online-Archiv für PHP und MySQL auf netcup-Webhosting eingerichtet.","Personensuche, Familienverbindungen und schematischer Stammbaum.","Registrierung, Anmeldung und Admin-Verwaltung.","Ergänzungen und Bilder werden vor der Übernahme durch einen Admin geprüft.","Teilbare Leselinks mit einstellbarer Sichtbarkeit und Widerruf.","Änderungsverlauf, Export und Schnittstelle für den lokalen Abgleich."]}];
const APP_VERSION=RELEASES[0].version;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
cleanCredentialUrl();
const S={user:null,archive:null,proposals:[],view:'persons',selected:null,q:'',page:0,share:location.hash.startsWith('#share=')?location.hash.slice(7):null,zoom:1,treeMode:'ancestors',desktop:false,maxUpload:8*1024*1024,imports:false,importOcr:false,importDraft:null};
const titles={persons:'Personen',tree:'Stammbaum',review:'Prüfliste',users:'Benutzer',shares:'Freigabelinks',sync:'Synchronisierung',issues:'Forschungsfragen',imports:'Linie importieren',detail:'Personendetails',edit:'Ergänzung einreichen',new:'Neue Person',account:'Mein Konto',upload:'Bild oder Scan hinzufügen',relationship:'Verbindung ergänzen'};
const fields={'anzeigename':'Name / Bezeichnung','namen.geburtsname':'Geburtsname / Mädchenname','geburt.datum.iso':'Geburtsdatum','geburt.ort_original':'Geburtsort','tod.datum.iso':'Sterbedatum','tod.ort_original':'Sterbeort','taufe.datum.iso':'Taufdatum','taufe.ort_original':'Taufort','bestattung.datum.iso':'Bestattungsdatum','bestattung.ort_original':'Bestattungsort','biografie':'Biografie'};
const path=(p,k)=>k.split('.').reduce((a,b)=>a?.[b],p);
const person=id=>S.archive?.personen.find(p=>p.id===id);
const name=id=>{const p=person(id);return p?p.anzeigename+(birthName(p)?' · geb. '+birthName(p):''):id;};
function birthName(p){const value=p?.namen?.geburtsname;return typeof value==='string'?value.trim():'';}
function birthNameLine(p){return birthName(p)?`<span class="birth-name">geb. ${esc(birthName(p))}</span>`:'';}
const initials=n=>String(n||'?').split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('');
function datum(p,k){const d=p?.[k]?.datum;if(d?.konflikt)return 'widersprüchlich';const v=d?.iso;if(!v)return 'unbekannt';return v.length===10?v.split('-').reverse().join('.'):v;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function api(url,opts={}){let r=await fetch(url,{credentials:'same-origin',...opts,headers:{...(opts.body&&typeof opts.body==='string'?{'Content-Type':'application/json'}:{}),...opts.headers}});let b=await r.json().catch(()=>({detail:'Antwort konnte nicht gelesen werden.'}));if(!r.ok)throw Error(typeof b.detail==='string'?b.detail:JSON.stringify(b.detail));return b;}
const post=(url,b)=>api(url,{method:'POST',body:JSON.stringify(b)});
async function reload(){S.archive=await api(S.share?'/api/shared/'+encodeURIComponent(S.share):'/api/archive');if(!S.share)S.proposals=await api('/api/proposals');if(!S.selected)S.selected=S.archive.personen.find(p=>/Florian/i.test(p.anzeigename))?.id||S.archive.personen.at(-1)?.id;}
async function boot(){try{if(location.hash.startsWith('#invite=')){const t=location.hash.slice(8);history.replaceState(null,'',location.pathname+location.search);await invitationView(t);return;}if(S.share){await reload();render();return;}S.user=await api('/api/me');S.desktop=S.user.desktop;const caps=await api('/api/capabilities');S.maxUpload=caps.max_upload_bytes;S.imports=!!caps.imports;S.importOcr=!!caps.import_ocr;if(!S.desktop&&S.user.role==='admin')await post('/api/corrections/adopt-template',{});await reload();render();if(!S.desktop)startEvidenceWatch();if(S.desktop)setInterval(checkSync,8000);}catch(e){if(S.share){$('#app').innerHTML=`<div class="login-form"><h1>Freigabelink</h1><p class="error">${esc(e.message)}</p></div>`;}else login();}}
function login(register=false){$('#app').innerHTML=`<div class="login"><div class="login-art"><div class="eyebrow">Familie Huschka · Ahnenarchiv</div><h1>Geschichten bleiben.<br>Generationen verbinden.</h1><p>Gemeinsam bewahren wir Namen, Erinnerungen und die Spuren unserer Familie.</p><p class="small">Personen · Familienlinien · Bilder & Quellen</p></div><div class="login-form"><div class="eyebrow">Willkommen im Familienarchiv</div><h2>${register?'Konto anlegen':'Anmelden'}</h2><form id="auth-form" method="post" action="${register?'/api/register':'/api/login'}" autocomplete="off" data-register="${register}">${register?'<label>Name</label><input name="name" required maxlength="200" autocomplete="name">':''}<label>E-Mail-Adresse</label><input name="email" type="email" required autocomplete="off" value=""><label>Passwort</label><input name="password" type="password" required minlength="12" maxlength="256" autocomplete="off" value=""><p id="form-error" class="error"></p><button class="primary" type="submit">${register?'Registrierung einreichen':'Archiv öffnen'}</button></form><p class="small muted">${register?'Neue Konten werden durch Flo oder Otto freigegeben.':'Bitte mit deinem eigenen Konto anmelden. Für neue Nutzer: Neues Konto anlegen.'}</p><button data-action="${register?'login':'register'}">${register?'Zur Anmeldung':'Neues Konto anlegen'}</button><div class="login-version">${versionButton()}</div></div></div>`;}
function shell(content){const admin=S.user?.role==='admin',pending=S.proposals.filter(p=>p.status==='pending').length;const nav=[['persons','Personen'],['tree','Stammbaum'],...(!S.share?[['review',`Prüfliste${pending?' · '+pending:''}`],['issues','Forschungsfragen'],...(S.imports?[['imports','Linie importieren']]:[])]:[]),...(admin?[['users','Benutzer'],['shares','Freigabelinks']]:[]),...(!S.share&&!S.desktop?[['account','Mein Konto']]:[]),...(S.desktop?[['sync','Synchronisierung']]:[])];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand-icon">♧</div><div class="brand">Ahnenarchiv</div><p class="muted">Familie Huschka<br>Gemeinsam Geschichte bewahren</p><nav>${nav.map(([v,n])=>`<button data-action="nav" data-view="${v}" class="${S.view===v?'active':''}">${esc(n)}</button>`).join('')}</nav><div class="release-summary">${versionButton()}</div><div class="foot"><strong>${esc(S.user?.name||'Geteiltes Archiv')}</strong><p class="muted">${S.share?'Nur Leserechte':admin?'Administrator':'Mitforschender'}</p>${!S.share&&!S.desktop?'<button data-action="logout">Abmelden</button>':''}</div></aside><main class="main"><header class="topbar"><span class="eyebrow">Familienforschung / ${esc(titles[S.view]||'Archiv')}</span><span class="badge" id="sync-status">${S.share?'Leseansicht':S.desktop?'Lokal gespeichert':'Gemeinsames Archiv'}</span></header>${content}</main></div>`;}
function render(){if(!S.archive)return;let html='';const p=person(S.selected);switch(S.view){case 'persons':html=personsView();break;case 'tree':html=treeView();break;case 'detail':html=detailView(p);break;case 'edit':html=editView(p);break;case 'new':html=newView();break;case 'upload':html=uploadView();break;case 'relationship':html=relationshipView();break;case 'review':html=reviewView();break;case 'issues':html=issuesView();break;case 'users':html='<h1>Benutzer & Rechte</h1>'+(!S.desktop?userAdminForms():'')+'<div id="remote-content">Wird geladen …</div><section class="card actions"><div><h2>Datenkorrekturen</h2><p>Vertauschte Porträts aus dem Erstimport prüfen und gemeinsam berichtigen.</p><button data-action="portrait-fix">Porträtkorrektur zur Prüfung anlegen</button><p>Eindeutige Verbindungen aus der ursprünglichen PDF werden seit Version 1.4.2 automatisch als belegt übernommen. Fragliche und individuell bewertete Verbindungen bleiben ausgenommen.</p></div></section>';break;case 'shares':html=sharesView();break;case 'imports':html=importsView();break;case 'account':html=accountView();break;case 'sync':html=syncView();break;}shell(html);if(S.view==='tree')drawTree();if(S.view==='users'){loadUsers();if(!S.desktop)loadInvitations();}if(S.view==='shares')loadShares();if(S.view==='imports'&&!S.importDraft)loadImports();if(S.desktop)checkSync();}
function personsView(){let matches=S.archive.personen.filter(p=>(p.anzeigename+' '+JSON.stringify(p.namen||{})).toLocaleLowerCase().includes(S.q.toLocaleLowerCase()));matches.sort((a,b)=>(a.anzeigename||'').localeCompare(b.anzeigename||'','de'));const page=matches.slice(S.page*30,S.page*30+30);return `<div class="hero"><div><div class="eyebrow">Unser Familiengedächtnis</div><h1>Menschen hinter den Namen.</h1><p class="muted">Finde eine Person, entdecke ihre Geschichte und ergänze fehlende Spuren.</p></div>${!S.share?'<button class="primary" data-action="nav" data-view="new">＋ Neue Person</button>':''}</div><div class="stats"><div class="stat"><strong>${S.archive.personen.length}</strong><span>Personen & Platzhalter</span></div><div class="stat"><strong>${S.archive.familien.length}</strong><span>Familienverbindungen</span></div><div class="stat"><strong>${S.archive.medien.length}</strong><span>Bilder & Dokumente</span></div></div><div class="toolbar"><input id="search" aria-label="Person suchen" type="search" placeholder="Name suchen, z. B. Anton Huschka" value="${esc(S.q)}"><span class="small muted">${matches.length} Treffer</span></div><div class="grid">${page.map(p=>`<button class="card person-card" data-action="person" data-id="${esc(p.id)}"><span class="arrow">↗</span><div class="initials">${esc(initials(p.anzeigename))}</div><h3>${esc(p.anzeigename)}</h3>${birthNameLine(p)}<div class="dates">* ${esc(datum(p,'geburt'))}<br>† ${esc(datum(p,'tod'))}</div><p class="small muted">${esc(p.geburt?.ort_original||'Ort noch nicht erfasst')}</p></button>`).join('')||'<div class="empty">Keine passende Person gefunden.</div>'}</div><div class="pagination"><button data-action="prev" ${S.page===0?'disabled':''}>Zurück</button><span>${S.page+1} / ${Math.max(1,Math.ceil(matches.length/30))}</span><button data-action="next" ${(S.page+1)*30>=matches.length?'disabled':''}>Weiter</button></div>`;}
function relationships(p){const rs=S.archive.beziehungen,parents=rs.filter(r=>r.typ==='eltern_kind'&&r.zu_person_id===p.id).map(r=>r.von_person_id),children=rs.filter(r=>r.typ==='eltern_kind'&&r.von_person_id===p.id).map(r=>r.zu_person_id),partners=S.archive.familien.filter(f=>f.partner_person_ids.includes(p.id)).flatMap(f=>f.partner_person_ids.filter(i=>i!==p.id));rs.filter(r=>r.typ==='partner'&&(r.von_person_id===p.id||r.zu_person_id===p.id)).forEach(r=>partners.push(r.von_person_id===p.id?r.zu_person_id:r.von_person_id));return {parents:[...new Set(parents)],children:[...new Set(children)],partners:[...new Set(partners)]};}
function links(ids){return ids.map(id=>`<button class="person-link" data-action="person" data-id="${esc(id)}">${esc(name(id))}</button>`).join('')||'<span class="muted small">Noch nicht erfasst</span>';}
function detailView(p){if(!p)return '<div class="empty">Person nicht gefunden.</div>';const rs=relationships(p),media=S.archive.medien.filter(m=>m.person_ids?.includes(p.id)||m.zuordnungen?.some(x=>x.person_id===p.id)||p.anhaenge?.some(a=>a.medium_id===m.id)),pending=S.proposals.filter(x=>x.target===p.id&&x.status==='pending');return `<button data-action="nav" data-view="persons">← Alle Personen</button><div class="hero"><div><h1>${esc(p.anzeigename)}</h1><p class="muted">${esc(birthName(p)?'Geburtsname: '+birthName(p):'')} ${p.datensatz_typ&&p.datensatz_typ!=='person'?' · '+esc(p.datensatz_typ):''}</p></div><button data-action="nav" data-view="tree">Im Stammbaum ansehen</button></div><div class="columns"><div><section class="card"><div class="eyebrow">Lebensdaten</div><div class="details">${['geburt','hochzeit','tod','taufe','bestattung'].map((k,i)=>`<div class="fact"><span>${['Geburt','Hochzeit (erste erfasste)','Tod','Taufe','Bestattung'][i]}</span><strong>${esc(datum(p,k))}</strong><p class="small muted">${esc(p[k]?.ort_original||'Ort unbekannt')}</p></div>`).join('')}<div class="fact"><span>Erfassungsstand</span>${esc(p.forschung?.status||'Freigegebener Bestand')}<p class="small muted">Freigabe ersetzt keinen historischen Beleg.</p></div></div>${p.biografie?`<p>${esc(p.biografie)}</p>`:''}${p.hochzeiten?.length>1?`<h3>Weitere Ehen</h3>${p.hochzeiten.map(h=>`<p>${esc(datum({hochzeit:h.ereignis},'hochzeit'))} · ${h.partner_person_ids.map(name).map(esc).join(', ')}</p>`).join('')}`:''}${!S.share?'<div class="actions"><button class="primary" data-action="nav" data-view="edit">Daten ergänzen</button><button data-action="nav" data-view="upload">Bild / Scan hinzufügen</button><button data-action="nav" data-view="relationship">Verbindung ergänzen</button></div>':''}</section><h2 class="actions">Bilder & Quellen</h2><div class="media-grid">${media.map(m=>{const url='/api/media/'+encodeURIComponent(m.id)+(S.share?'?share='+encodeURIComponent(S.share):'');return `<a href="${url}" ${m.mime_type?.startsWith('image/')?'data-image-popup':'target="_blank" rel="noopener"'}>${m.mime_type?.startsWith('image/')?`<img src="${url}" loading="lazy" alt="${esc(m.titel||'Familienbild')}">`:'<div class="card">PDF / Dokument ↗</div>'}<p>${esc(m.titel)}</p></a>`;}).join('')||'<p class="muted">Noch keine zugeordneten Dateien.</p>'}</div></div><aside><section class="card"><h2>Familienverbindungen</h2><label>Eltern</label>${connectionLinks(p,rs.parents)}<label>Partner</label>${connectionLinks(p,rs.partners,true)}<label>Kinder</label>${connectionLinks(p,rs.children)}<p class="small muted">Belegstatus der Verbindung und unbekannte Namen werden getrennt geführt.</p></section>${!S.share?`<section class="card actions"><h3>Quellen & Forschungsstand</h3><div class="source">${esc((p.quellen_verweise||[]).map(q=>'PDF-Seite '+q.seite).filter((v,i,a)=>a.indexOf(v)===i).join(', ')||'Noch keine Quellenangabe')}</div>${p.notizen?.length?`<p class="small">${esc(JSON.stringify(p.notizen))}</p>`:''}<p class="small muted">${pending.length} offene Ergänzung(en)</p><button data-action="history" data-id="${esc(p.id)}">Änderungsverlauf</button><div id="history"></div></section>`:''}</aside></div>`;}
function editView(p){return `<h1>${esc(p?.anzeigename)}</h1><p class="muted">Deine Angaben werden als Vorschlag gespeichert. Der bisherige Bestand bleibt bis zur Freigabe erhalten.</p><form id="edit-form" class="card"><div class="form-grid">${Object.entries(fields).map(([key,label])=>`<div class="${key==='biografie'?'span2':''}"><label>${esc(label)}</label>${key==='biografie'?`<textarea name="${key}">${esc(path(p,key)||'')}</textarea>`:`<input name="${key}" value="${esc(path(p,key)||'')}" ${key.includes('datum')?'placeholder="JJJJ oder JJJJ-MM-TT"':''}>`}</div>`).join('')}<div class="span2"><label>Quelle / Woher weißt du das?</label><textarea name="source" placeholder="Zum Beispiel: Sterbeurkunde, Familiengespräch, Archivsignatur"></textarea></div></div><p id="form-error" class="error"></p><div class="actions"><button class="primary">Zur Prüfung speichern</button><button type="button" data-action="nav" data-view="detail">Abbrechen</button></div></form>`;}
function newView(){return `<h1>Eine neue Spur.</h1><p class="muted">Neue Personen erscheinen nach Freigabe im Stammbaum. Bei unbekanntem Namen eine eindeutige vorläufige Bezeichnung verwenden.</p><form id="new-form" class="card"><div class="form-grid"><div class="span2"><label>Name / Vorläufige Bezeichnung</label><input name="anzeigename" required maxlength="200" placeholder="Anton Huschka oder Unbekannter Mann auf Foto …"></div><div><label>Geburtsdatum</label><input name="birth" placeholder="JJJJ-MM-TT"></div><div><label>Sterbedatum</label><input name="death" placeholder="JJJJ-MM-TT"></div><div><label>Geburtsort</label><input name="birthplace"></div><div><label>Sterbeort</label><input name="deathplace"></div><div class="span2"><label>Quelle und Beschreibung</label><textarea name="source" required></textarea></div></div><p class="small muted">Familienverbindungen lassen sich ergänzen, sobald die Person freigegeben ist. Ein Bild kann bereits dem Personenvorschlag zugeordnet werden.</p><p id="form-error" class="error"></p><button class="primary">Neue Person zur Prüfung speichern</button></form>`;}
function options(includePending=false){let list=S.archive.personen.map(p=>({id:p.id,name:name(p.id)}));if(includePending)list.push(...S.proposals.filter(p=>p.kind==='person'&&p.status==='pending').map(p=>({id:p.target,name:p.payload.anzeigename+' · wartet auf Freigabe'})));return list.sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}" ${p.id===S.selected?'selected':''}>${esc(p.name)}</option>`).join('');}
function uploadView(){return `<h1>Erinnerungen bewahren.</h1><p class="muted">Jede Datei braucht einen Titel und eine Personenzuordnung. Die Zuordnung wird geprüft.</p><form id="upload-form" class="card"><label>Person suchen</label><input id="person-filter" type="search" placeholder="Liste nach Namen filtern"><label>Person(en) – Mehrfachauswahl mit Strg</label><select name="persons" id="upload-persons" multiple size="7" required>${options(true)}</select><label>Bildtitel / Beschreibung</label><input name="title" required maxlength="200" placeholder="Hochzeitsfoto von …"><label>Bild oder Scan</label><input name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required><p class="small muted">JPG, PNG, WebP oder PDF · maximal ${Math.floor(S.maxUpload/1024/1024)} MB · große Fotos werden vor dem Upload verkleinert</p><label>Quelle / Herkunft</label><textarea name="source"></textarea><p id="form-error" class="error"></p><button class="primary">Datei zur Prüfung speichern</button></form>`;}
function relationshipView(){return `<h1>Familienverbindung ergänzen</h1><form id="relationship-form" class="card"><label>Person A</label><select name="from">${options()}</select><label>Verbindung</label><select name="type"><option value="eltern_kind">A ist Elternteil von B</option><option value="partner">A und B sind Partner</option></select><label>Person B</label><select name="to">${options()}</select><label>Art der Elternschaft</label><select name="parenttype"><option value="ungeklaert">Noch ungeklärt</option><option value="biologisch">Biologisch, durch Beleg bestätigt</option><option value="adoptiv">Adoptiv</option><option value="pflege">Pflege</option><option value="stief">Stief</option></select><label>Quelle / Begründung</label><textarea name="source" required></textarea><p id="form-error" class="error"></p><button class="primary">Verbindung zur Prüfung speichern</button></form>`;}
function reviewView(){let rows=S.proposals.filter(p=>p.status==='pending');return `<div class="hero"><div><h1>Hinweise gemeinsam prüfen.</h1><p class="muted">${S.user?.role==='admin'?'Bestätige belegte Ergänzungen oder gib Rückmeldung.':'Hier siehst du deine noch offenen Ergänzungen.'}</p></div><button data-action="refresh">Aktualisieren</button></div>${rows.map(p=>{let info=['relationship_status','template_confirmation'].includes(p.kind)?connectionReview(p):p.kind==='relationship_confirmation'?familyConfirmationReview(p):p.kind==='portrait_fix'?portraitFixReview(p):p.kind==='import'?importReview(p):p.kind==='patch'?Object.entries(p.payload.changes).map(([k,v])=>`<label>${esc(fields[k]||k)}</label><div class="review-row"><div class="before"><small>Bisher / Stand bei Einreichung</small>${esc(p.payload.before?.[k]||'unbekannt')}</div><div class="after"><small>Vorschlag</small>${esc(v||'unbekannt')}</div></div>`).join(''):p.kind==='person'?`<h3>${esc(p.payload.anzeigename)}</h3><p>Geburt: ${esc(datum(p.payload,'geburt'))} · Tod: ${esc(datum(p.payload,'tod'))}</p>`:p.kind==='relationship'?`<p>${esc(name(p.payload.von_person_id))} ${p.payload.typ==='partner'?'↔ Partner von':'→ Elternteil von'} ${esc(name(p.payload.zu_person_id))}</p>`:`<p>${esc(p.payload.titel)} · ${(p.payload.person_ids||[]).map(name).map(esc).join(', ')}</p><a href="/api/media/${esc(p.payload.upload_id)}" target="_blank" rel="noopener">Beleg öffnen ↗</a>`;return `<section class="card review-card"><div class="topbar"><strong>${esc(['relationship_status','template_confirmation'].includes(p.kind)?'Belegstatus von Familienverbindungen':p.kind==='relationship_confirmation'?'Belegte Familienverbindungen bestätigen':p.kind==='portrait_fix'?'Porträtzuordnungen korrigieren':p.kind==='import'?p.payload.title:p.kind==='person'?'Neue Person':name(p.target))}</strong><span class="badge ${p.status}">${{pending:'Wartet auf Freigabe',approved:'Freigegeben',rejected:'Abgelehnt'}[p.status]||esc(p.status)}</span></div>${info}<div class="source">${esc(p.source||'Keine Quelle angegeben')}</div><p class="small muted">Eingereicht ${esc(new Date(p.created).toLocaleString('de-DE'))}${p.reason?' · '+esc(p.reason):''}</p>${S.user?.role==='admin'&&p.status==='pending'?`<div class="actions"><button class="primary" data-action="approve" data-id="${esc(p.id)}">Prüfung bestätigen & freigeben</button><button class="danger" data-action="reject" data-id="${esc(p.id)}">Ablehnen</button></div>`:''}</section>`;}).join('')||'<div class="empty">Alles geprüft. Aktuell sind keine offenen Vorschläge vorhanden.</div>'}`;}
function issuesView(){return `<h1>Offene Forschungsfragen</h1><p class="muted">Auswertung der Vorlage. Diese Hinweise bleiben beim Import erhalten.</p>${S.archive.pruefhinweise.map(x=>`<section class="card review-card"><h3>${esc(x.titel||x.typ||x.id)}</h3><p>${esc(x.beschreibung||x.hinweis||x.problem||JSON.stringify(x))}</p></section>`).join('')}`;}
function treeView(){return `<h1>Von Generation zu Generation.</h1><p class="muted">Ältere Generationen oben, jüngere unten. Eine Person anklicken, um ihre Daten zu öffnen. Ein gemeinsamer Familienzweig verbindet Eltern und ihre Kinder. Grüne Linien verbinden Eltern und Kinder, goldene Linien verbinden Partner.</p><div class="toolbar"><select id="tree-person" aria-label="Ausgangspunkt">${options()}</select><select id="tree-mode" aria-label="Ansicht"><option value="ancestors" ${S.treeMode==='ancestors'?'selected':''}>Direkte Vorfahren</option><option value="family" ${S.treeMode==='family'?'selected':''}>Nahe Familie</option><option value="all" ${S.treeMode==='all'?'selected':''}>Gesamter Bestand</option></select><button data-action="zoom-out">−</button><span>${Math.round(S.zoom*100)} %</span><button data-action="zoom-in">＋</button><button data-action="zoom-reset">Ansicht zurücksetzen</button></div><div class="legend"><span><i class="line-symbol partner"></i>Partner</span><span><i class="line-symbol"></i>Belegte Elternschaft</span><span><i class="line-symbol uncertain"></i>Elternschaft noch nicht bestätigt</span></div><div class="tree-wrap" id="tree"></div>`;}
function drawTree(){const all=S.archive.personen,byId=new Map(all.map(p=>[p.id,p])),rels=S.archive.beziehungen.filter(r=>r.typ==='eltern_kind'&&byId.has(r.von_person_id)&&byId.has(r.zu_person_id));let ids=new Set(S.treeMode==='all'?all.map(p=>p.id):[S.selected]);if(S.treeMode==='ancestors'){let stack=[S.selected];while(stack.length){let id=stack.pop();for(const r of rels.filter(r=>r.zu_person_id===id))if(!ids.has(r.von_person_id)){ids.add(r.von_person_id);stack.push(r.von_person_id);}}}if(S.treeMode==='family'){for(let step=0;step<2;step++){let before=[...ids];for(let id of before){let p=byId.get(id);if(p)Object.values(relationships(p)).flat().forEach(x=>ids.add(x));}}}const ps=all.filter(p=>ids.has(p.id)),edges=rels.filter(r=>ids.has(r.von_person_id)&&ids.has(r.zu_person_id));let ranks=new Map(ps.map(p=>[p.id,0]));for(let pass=0;pass<ps.length;pass++){let changed=false;for(let r of edges){let val=ranks.get(r.von_person_id)+1;if(val>ranks.get(r.zu_person_id)){ranks.set(r.zu_person_id,val);changed=true;}}if(!changed)break;}const partners=[];S.archive.familien.forEach(f=>{const pp=f.partner_person_ids.filter(i=>ids.has(i));for(let i=1;i<pp.length;i++)partners.push([pp[0],pp[i],f]);});S.archive.beziehungen.filter(r=>r.typ==='partner'&&ids.has(r.von_person_id)&&ids.has(r.zu_person_id)).forEach(r=>partners.push([r.von_person_id,r.zu_person_id,r]));for(let pass=0;pass<ps.length;pass++){let changed=false;for(let [a,b] of partners){let rank=Math.max(ranks.get(a),ranks.get(b));if(ranks.get(a)!==rank||ranks.get(b)!==rank){ranks.set(a,rank);ranks.set(b,rank);changed=true;}}for(let r of edges){let val=ranks.get(r.von_person_id)+1;if(val>ranks.get(r.zu_person_id)){ranks.set(r.zu_person_id,val);changed=true;}}if(!changed)break;}const groups=new Map();for(let p of ps){let rank=ranks.get(p.id);if(!groups.has(rank))groups.set(rank,[]);groups.get(rank).push(p);}let levels=[...groups.keys()].sort((a,b)=>a-b),levelIndex=new Map(levels.map((r,i)=>[r,i])),longCount=edges.filter(r=>levelIndex.get(ranks.get(r.zu_person_id))-levelIndex.get(ranks.get(r.von_person_id))>1).length,gutter=longCount?longCount*8+40:0,width=Math.max(800,...[...groups.values()].map(g=>g.length*230+80))+gutter*2,height=levels.length*190+80,pos=new Map();levels.forEach((rank,li)=>{const row=groups.get(rank),rowIds=new Set(row.map(p=>p.id)),seen=new Set(),units=[];for(const p of row){if(seen.has(p.id))continue;const stack=[p.id],unit=[];seen.add(p.id);while(stack.length){const id=stack.pop();unit.push(byId.get(id));for(const [a,b] of partners){const other=a===id?b:b===id?a:null;if(other&&rowIds.has(other)&&!seen.has(other)){seen.add(other);stack.push(other);}}}const ancestors=edges.filter(r=>unit.some(p=>p.id===r.zu_person_id)&&pos.has(r.von_person_id)).map(r=>pos.get(r.von_person_id).x+98);unit.sort((a,b)=>{const hasParents=id=>edges.some(r=>r.zu_person_id===id);return Number(hasParents(b.id))-Number(hasParents(a.id))||(a.anzeigename||'').localeCompare(b.anzeigename||'','de');});units.push({people:unit,anchor:ancestors.length?ancestors.reduce((a,b)=>a+b,0)/ancestors.length:null,label:unit.map(p=>p.anzeigename).join(' ')});}units.sort((a,b)=>a.anchor!==null&&b.anchor!==null?a.anchor-b.anchor||a.label.localeCompare(b.label,'de'):a.anchor!==null?-1:b.anchor!==null?1:a.label.localeCompare(b.label,'de'));const ordered=units.flatMap(u=>u.people);ordered.forEach((p,i)=>pos.set(p.id,{x:(width-ordered.length*230)/2+i*230+16,y:li*190+35}));});let lines=familyBranchPaths(edges,pos);lines+=partners.map(([a,b,r])=>{let x=pos.get(a),y=pos.get(b);let left=x.x<y.x?x:y,right=x.x<y.x?y:x;let d=x.y===y.y&&right.x-left.x<=230?`M${left.x+196},${left.y+55} H${right.x}`:`M${x.x+98},${x.y} V${Math.min(x.y,y.y)-14} H${y.x+98} V${y.y}`;return `<path class="partner-edge" d="${d}" stroke="#b48d45" stroke-width="2" fill="none" ${r?.belegstatus==='ungeklaert'?'stroke-dasharray="5 4"':''}/>`;}).join('');let nodes=ps.map(p=>{let a=pos.get(p.id);return `<foreignObject x="${a.x}" y="${a.y}" width="196" height="110"><button xmlns="http://www.w3.org/1999/xhtml" class="tree-node ${p.id===S.selected?'selected':''}" data-action="person" data-id="${esc(p.id)}"><strong>${esc(p.anzeigename)}</strong>${birthNameLine(p)}<small>* ${esc(datum(p,'geburt'))} · † ${esc(datum(p,'tod'))}</small></button></foreignObject>`;}).join('');$('#tree').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" width="${width*S.zoom}" height="${height*S.zoom}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Familienstammbaum">${lines}${nodes}</svg>`;const focus=pos.get(S.selected);if(focus){$('#tree').scrollLeft=Math.max(0,focus.x*S.zoom-$('#tree').clientWidth/2+100);$('#tree').scrollTop=Math.max(0,focus.y*S.zoom-$('#tree').clientHeight/2);}}
function sharesView(){return `<h1>Familie einladen.</h1><p class="muted">Freigabelinks erlauben ausschließlich Lesen. Lebende Personen und Medien bleiben standardmäßig ausgeblendet.</p><form id="share-form" class="card"><label>Bezeichnung</label><input name="name" required placeholder="Zum Beispiel: Huschka-Linie für Familie Müller"><label>Bereich</label><select name="scope"><option value="all">Alle sichtbaren verstorbenen Personen</option><option value="ancestors">Vorfahren der ausgewählten Person: ${esc(name(S.selected))}</option></select><label class="checkbox"><input type="checkbox" name="living">Lebende Personen ausdrücklich einbeziehen</label><label class="checkbox"><input type="checkbox" name="media">Zugeordnete Bilder freigeben</label><p class="small muted">Gruppenbilder werden nur angezeigt, wenn alle zugeordneten Personen im Freigabebereich liegen.</p><button class="primary">Leselink erstellen</button><div id="new-share"></div></form><h2 class="actions">Bestehende Freigaben</h2><div id="remote-content"></div>`;}
function syncView(){return `<h1>Lokal arbeiten. Gemeinsam forschen.</h1><section class="card"><h2>Abgleich</h2><div id="sync-detail">Status wird geladen …</div><button class="primary" data-action="sync">Jetzt abgleichen</button></section><form method="post" action="/api/desktop/connect" id="connect-form" class="card actions"><div class="full-width"><h2>Onlineverbindung einrichten</h2><p class="muted">Einmal Serveradresse und dein Konto eintragen. Die App gleicht danach automatisch ab.</p><label>Serveradresse</label><input name="url" type="url" required placeholder="https://stammbaum-huschka.de"><label>E-Mail-Adresse</label><input name="email" type="email" required autocomplete="username"><label>Passwort</label><input name="password" type="password" required autocomplete="current-password"><p id="form-error" class="error"></p><button class="primary">Verbinden</button></div></form>`;}
async function loadUsers(){try{let us=await api('/api/users');$('#remote-content').innerHTML=`<table class="table"><thead><tr><th>Name</th><th>Rolle</th><th>Status</th><th>Aktion</th></tr></thead><tbody>${us.map(u=>`<tr><td>${esc(u.name)}<br><span class="small muted">${esc(u.email)}</span></td><td>${esc(u.role)}</td><td>${u.active?'Aktiv':'Wartet auf Freigabe'}</td><td><button data-action="user-activate" data-id="${u.id}" data-role="${u.role}" data-active="${!u.active}">${u.active?'Deaktivieren':'Freigeben'}</button> <button data-action="user-role" data-id="${u.id}" data-role="${u.role==='admin'?'member':'admin'}" data-active="${u.active}">${u.role==='admin'?'Zu Mitglied':'Zu Admin'}</button></td></tr>`).join('')}</tbody></table>`;}catch(e){$('#remote-content').textContent=e.message;}}
async function loadShares(){try{let ss=await api('/api/shares');$('#remote-content').innerHTML=ss.map(s=>`<div class="card review-card"><strong>${esc(s.name)}</strong><p>${s.active?'Aktiv':'Widerrufen'} · ${s.data.include_living?'Mit lebenden Personen':'Lebende Personen ausgeblendet'}</p>${s.active?`<button class="danger" data-action="revoke" data-id="${s.id}">Link sperren</button>`:''}</div>`).join('')||'<p class="muted">Noch keine Freigabelinks.</p>';}catch(e){$('#remote-content').textContent=e.message;}}
async function checkSync(){try{let s=await api('/api/desktop/status');if($('#sync-status'))$('#sync-status').textContent=s.queued?s.queued+' Übertragung(en) ausstehend':s.message;if($('#sync-detail'))$('#sync-detail').innerHTML=`<p>${esc(s.message)}</p><p class="muted">${s.queued} Übertragung(en) ausstehend<br>Letzter Abgleich: ${s.last_sync?esc(new Date(s.last_sync).toLocaleString('de-DE')):'noch keiner'}</p>${s.errors.length?`<p class="error">${s.errors.map(esc).join('<br>')}</p>`:''}`;if(s.last_sync&&S.lastSync!==s.last_sync){S.lastSync=s.last_sync;S.user=await api('/api/me');await reload();if(['persons','review','tree','detail'].includes(S.view))render();}}catch(e){/* Local service remains readable while network is absent. */}}
async function history(id){let rows=await api(S.desktop?'/api/desktop/history/'+id:'/api/audit/'+id);$('#history').innerHTML=rows.map(a=>`<div class="source actions"><div>${esc(a.action)} · ${esc(new Date(a.created).toLocaleString('de-DE'))}<p class="small">${esc(a.data.source||'')}</p>${S.user?.role==='admin'&&a.data.before?`<button data-action="restore" data-id="${a.id}">Vorherigen Stand wiederherstellen</button>`:''}</div></div>`).join('')||'<p class="muted">Bisher keine Änderungen.</p>';}
document.addEventListener('click',async event=>{let el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{if(a==='nav'){S.view=el.dataset.view;render();}else if(a==='person'){S.selected=el.dataset.id;S.view='detail';render();}else if(a==='login'||a==='register')login(a==='register');else if(a==='logout'){await post('/api/logout',{});S.user=null;login();}else if(a==='prev'||a==='next'){S.page+=a==='next'?1:-1;render();}else if(a.startsWith('zoom')){S.zoom=a==='zoom-reset'?1:Math.max(.3,Math.min(2,S.zoom+(a==='zoom-in'?.15:-.15)));render();}else if(a==='refresh'){await reload();render();}else if(a==='approve'||a==='reject'){let reason='';if(a==='approve'&&!confirm('Geprüfte Angaben in den gemeinsamen Bestand übernehmen?'))return;if(a==='reject'){reason=prompt('Begründung für die Ablehnung:');if(reason===null)return;}el.disabled=true;await post('/api/proposals/'+el.dataset.id+'/review',{decision:a==='approve'?'approve':'reject',reason});await reload();render();toast(a==='approve'?'Ergänzung freigegeben.':'Vorschlag abgelehnt.');}else if(a==='history')await history(el.dataset.id);else if(a==='restore'){if(!confirm('Vorherigen Stand wiederherstellen?'))return;await post('/api/audit/'+el.dataset.id+'/restore',{});await reload();render();toast('Vorheriger Stand wiederhergestellt.');}else if(a==='user-activate'||a==='user-role'){await post('/api/users/'+el.dataset.id,{role:el.dataset.role,active:el.dataset.active==='true'});await loadUsers();}else if(a==='revoke'){await post('/api/shares/'+el.dataset.id+'/revoke',{});await loadShares();toast('Freigabelink gesperrt.');}else if(a==='sync'){await post('/api/desktop/sync',{});toast('Abgleich gestartet.');}}catch(e){toast(e.message);el.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let start=e.target.selectionStart;S.q=e.target.value;S.page=0;render();$('#search').focus();$('#search').setSelectionRange(start,start);}if(e.target.id==='person-filter'){let q=e.target.value.toLocaleLowerCase();for(let o of $('#upload-persons').options)o.hidden=!o.textContent.toLocaleLowerCase().includes(q);}});
document.addEventListener('change',e=>{if(e.target.id==='tree-person'){S.selected=e.target.value;render();}if(e.target.id==='tree-mode'){S.treeMode=e.target.value;render();}});
document.addEventListener('submit',async e=>{if(['import-upload-form','connection-status-form','admin-user-form','admin-invite-form','accept-invite-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button.primary');if(button)button.disabled=true;try{if(f.id==='password-form'){if(b.new_password!==b.repeat)throw Error('Neue Passwörter unterscheiden sich.');await post('/api/account/password',b);f.reset();S.user=null;S.archive=null;S.proposals=[];S.view='persons';login();toast('Passwort geändert. Alle bisherigen Sitzungen wurden abgemeldet. Bitte neu anmelden.');return;}if(f.id==='auth-form'){if(f.dataset.register==='true'){let r=await post('/api/register',b);toast(r.message);login();}else{await post('/api/login',b);f.reset();await boot();}return;}if(f.id==='edit-form'){let p=person(S.selected),changes={};for(let key of Object.keys(fields)){let value=b[key]||null;if(value!==(path(p,key)||null))changes[key]=value;}if(!Object.keys(changes).length)throw Error('Keine Änderung eingetragen.');await post('/api/proposals',{kind:'patch',target:p.id,base_version:p.version,payload:{changes},source:b.source});}if(f.id==='new-form'){await post('/api/proposals',{kind:'person',payload:{anzeigename:b.anzeigename,geburt:{datum:{iso:b.birth||null},ort_original:b.birthplace||null},tod:{datum:{iso:b.death||null},ort_original:b.deathplace||null}},source:b.source});}if(f.id==='relationship-form'){await post('/api/proposals',{kind:'relationship',payload:{typ:b.type,von_person_id:b.from,zu_person_id:b.to,elternschaft_typ:b.parenttype},source:b.source});}if(f.id==='upload-form'){let ids=[...f.elements.persons.selectedOptions].map(x=>x.value),file=f.elements.file.files[0];if(!file||!ids.length)throw Error('Bitte Datei und Person auswählen.');file=await prepareUpload(file,S.maxUpload);let r=await api('/api/upload',{method:'POST',headers:{'x-title':encodeURIComponent(b.title),'x-person-ids':ids.join(',')},body:file});await post('/api/proposals',{kind:'media',payload:{upload_id:r.id,titel:b.title,person_ids:ids},source:b.source});}if(f.id==='share-form'){let ids=[];if(b.scope==='ancestors'){ids=[S.selected];for(let i=0;i<ids.length;i++)for(let r of S.archive.beziehungen.filter(r=>r.typ==='eltern_kind'&&r.zu_person_id===ids[i]))if(!ids.includes(r.von_person_id))ids.push(r.von_person_id);}let r=await post('/api/shares',{name:b.name,person_ids:ids,include_living:!!b.living,allow_media:!!b.media});$('#new-share').innerHTML=`<p class="success">Leselink erstellt. Kopiere ihn jetzt – er wird nur einmal angezeigt.</p><input aria-label="Freigabelink" value="${esc(r.url)}" readonly><p class="small muted">Der Link kann unten jederzeit gesperrt werden.</p>`;await loadShares();return;}if(f.id==='connect-form'){await post('/api/desktop/connect',b);f.elements.password.value='';toast('Verbindung eingerichtet. Abgleich läuft.');return;}await reload();S.view='review';render();toast(S.desktop?'Lokal gespeichert. Wird beim nächsten Abgleich übertragen.':'Vorschlag gespeichert. Wartet auf Freigabe.');}catch(err){const target=f.querySelector('#form-error');if(target)target.textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}});
async function prepareUpload(file,max){
 if(file.size<=max)return file;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error(`Datei zu groß. PDF bitte auf höchstens ${Math.floor(max/1024/1024)} MB aufteilen.`);
 const bitmap=await createImageBitmap(file);
 try{let scale=Math.min(1,3000/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas'),ctx=c.getContext('2d');
 for(let pass=0;pass<5;pass++){c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bitmap,0,0,c.width,c.height);
 const blob=await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.88));if(blob&&blob.size<=max){toast('Großes Bild für den Upload verkleinert. Die Originaldatei bleibt auf deinem Rechner.');return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'});}scale*=.75;
 }throw Error('Bild konnte nicht ausreichend verkleinert werden.');}finally{bitmap.close();}
}


// Native modal keeps keyboard focus inside the image viewer.
function openImagePopup(link){
  const preview=link.querySelector('img');
  if(!preview)return;
  document.querySelector('#image-popup')?.close();
  const dialog=document.createElement('dialog');
  dialog.id='image-popup';dialog.className='image-popup';
  dialog.setAttribute('aria-labelledby','image-popup-title');
  dialog.innerHTML='<div class="image-popup-bar"><strong id="image-popup-title"></strong><button type="button" aria-label="Bild schließen" autofocus>✕</button></div><div class="image-popup-stage"><img></div><p class="image-popup-hint">Bild anklicken zum Vergrößern · Escape zum Schließen</p>';
  dialog.querySelector('strong').textContent=preview.alt;
  const image=dialog.querySelector('img');
  image.src=link.href;image.alt=preview.alt;image.draggable=false;
  const stage=dialog.querySelector('.image-popup-stage');
  image.addEventListener('click',()=>stage.classList.toggle('is-zoomed'));
  dialog.querySelector('button').addEventListener('click',()=>dialog.close());
  dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
  const previousOverflow=document.body.style.overflow;
  dialog.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;dialog.remove();if(link.isConnected)link.focus();},{once:true});
  document.body.append(dialog);dialog.showModal();document.body.style.overflow='hidden';
}
document.addEventListener('click',event=>{const link=event.target.closest('a[data-image-popup]');if(link){event.preventDefault();openImagePopup(link);}});

function importsView(){
  const d=S.importDraft;
  return `<div class="hero"><div><h1>Eine neue Familienlinie.</h1><p class="muted">Einlesen → Angaben und Zuordnungen prüfen → zur Freigabe einreichen.</p></div></div><form id="import-upload-form" class="card"><label>Bezeichnung / Quelle</label><input name="title" required maxlength="200" placeholder="Zum Beispiel Schiessl–März-Linie"><label>Datei</label><input name="file" type="file" accept=".json,.ged,.gedcom,.pdf,.png,.jpg,.jpeg" required><p class="small muted">Bis ${(S.maxUpload/1024/1024).toFixed(0)} MB und 500 Personen pro Import. JSON und GEDCOM werden auf unserem Server verarbeitet.</p><p class="small">${S.importOcr?'PDF und Bilder: automatische Erkennung verfügbar.':'PDF und Bilder: automatische Erkennung benötigt noch einen API-Schlüssel in der Serverkonfiguration.'}</p>${S.user.role==='admin'?'<label class="checkbox"><input name="ocr" type="checkbox">Für PDF-/Bilderkennung: diese Datei an OpenAI übertragen (kostenpflichtige API). Alle Ergebnisse anschließend prüfen.</label>':'<p class="small muted">PDF-/Bilderkennung kann ein Admin ausführen.</p>'}<p id="form-error" class="error" role="status"></p><button class="primary" type="submit">Datei einlesen</button></form>${d?`<section class="card actions"><div class="full-width"><h2>Importentwurf: ${esc(d.title)}</h2><a href="/api/media/${esc(d.media_id)}" target="_blank" rel="noopener">Originalquelle ansehen ↗</a><p>${d.data.personen.length} Personen · ${d.data.beziehungen.length} Verbindungen</p>${d.data.hinweise.map(w=>`<p class="source">${esc(w)}</p>`).join('')}<label for="import-json">Erkannte Daten korrigieren (JSON)</label><textarea id="import-json" class="import-json" spellcheck="false">${esc(JSON.stringify(d.data,null,2))}</textarea><p class="small muted">Ändere hier auch Namen, Datumsangaben oder Verbindungen. Quell-IDs müssen eindeutig bleiben; unbekannte Daten bleiben null.</p><button data-action="import-preview">Korrekturen prüfen & Zuordnung anzeigen</button><div id="import-mapping"></div><p id="import-error" class="error" role="status"></p></div></section>`:'<h2 class="actions">Gespeicherte Importentwürfe</h2><div id="import-list">Wird geladen …</div>'}`;
}
async function loadImports(){try{const rows=await api('/api/imports');const el=$('#import-list');if(el)el.innerHTML=rows.map(d=>`<section class="card"><strong>${esc(d.title)}</strong><p>${d.persons} Personen · ${esc(new Date(d.created).toLocaleString('de-DE'))}</p><button data-action="import-open" data-id="${esc(d.id)}">Entwurf öffnen</button></section>`).join('')||'<p class="muted">Noch keine Importentwürfe.</p>';}catch(e){toast(e.message);}}
function importPreview(){
  const data=JSON.parse($('#import-json').value);if(!Array.isArray(data.personen)||!data.personen.length)throw Error('Keine Personen im JSON.');
  const existing=S.archive.personen.slice().sort((a,b)=>a.anzeigename.localeCompare(b.anzeigename,'de'));
  const label=p=>`${p.anzeigename} · * ${datum(p,'geburt')} · ${p.id}`;
  const rows=data.personen.map((p,i)=>{const matches=existing.filter(e=>e.anzeigename.toLocaleLowerCase()===String(p.anzeigename).toLocaleLowerCase()||p.namen?.familienname&&e.namen?.familienname===p.namen.familienname);return `<section class="import-person"><strong>${esc(p.anzeigename)}</strong><p class="small">* ${esc(datum(p,'geburt'))} · † ${esc(datum(p,'tod'))}</p><label>Übernahme</label><select data-import-choice="${i}"><option value="new">Neue Person anlegen</option><option value="existing" ${matches.length?'selected':''}>Bestehender Person zuordnen</option><option value="skip">Überspringen</option></select><label>Bestehende Person (bei Zuordnung auswählen)</label><input data-import-existing="${i}" list="import-existing-people" autocomplete="off" placeholder="Name suchen …"><p class="small muted">${matches.length?'Mögliche Dubletten: '+matches.slice(0,5).map(label).map(esc).join('; '):'Keine Namensübereinstimmung gefunden. Bei Namensvarianten trotzdem prüfen.'}</p></section>`;}).join('');
  $('#import-mapping').innerHTML=`<h3 class="actions">Personen zuordnen</h3><p class="small">Eine bestehende Person wird ausdrücklich ausgewählt. Fehlende Angaben werden ergänzt; widersprüchliche Werte bleiben erhalten und werden in der Prüfliste aufgeführt. Die Zuordnung verbindet auch die neue Linie mit dem vorhandenen Stammbaum.</p><datalist id="import-existing-people">${existing.map(p=>`<option value="${esc(label(p))}"></option>`).join('')}</datalist><div class="import-people">${rows}</div><button class="primary actions" data-action="import-submit">Import zur Freigabe einreichen</button>`;
  S.importDraft.preview=data;
}
function importReview(p){const plan=p.payload.plan;return `<p><strong>${plan.new.length}</strong> neue Personen · <strong>${plan.patches.length}</strong> Zuordnungen · <strong>${plan.relationships.length}</strong> neue Verbindungen</p><a href="/api/imports/${esc(p.payload.draft_id)}" data-action="import-open" data-id="${esc(p.payload.draft_id)}">Entwurf & Originalquelle prüfen</a>${plan.warnings.map(w=>`<p class="source">${esc(w)}</p>`).join('')}<details><summary>Alle Angaben und Verbindungen anzeigen</summary><h3 class="actions">Neue Personen</h3>${plan.new.map(per=>`<p><strong>${esc(per.anzeigename)}</strong> · * ${esc(datum(per,'geburt'))} · † ${esc(datum(per,'tod'))}<br>${esc(per.biografie||'')}</p>`).join('')}<h3 class="actions">Bestehende Personen ergänzen</h3>${plan.patches.map(per=>`<p><strong>${esc(per.name)}</strong>: ${esc(Object.entries(per.changes).map(([k,v])=>(fields[k]||k)+': '+v).join(' · ')||'Nur verknüpfen, keine Änderungen')}</p>`).join('')}<h3 class="actions">Verbindungen</h3>${plan.relationships.map(r=>`<p>${esc(plan.new.find(per=>per.id===r.von_person_id)?.anzeigename||name(r.von_person_id))} ${r.typ==='partner'?'↔ Partner':'→ Elternteil'} ${esc(plan.new.find(per=>per.id===r.zu_person_id)?.anzeigename||name(r.zu_person_id))}</p>`).join('')}<label>Vollständige Importdaten</label><pre class="code">${esc(JSON.stringify(plan,null,2))}</pre></details><p class="small muted">Die Freigabe übernimmt die Linie gemeinsam. Bei einem Konflikt wird keine Teilmenge gespeichert.</p>`;}
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
  if(!['import-open','import-preview','import-submit'].includes(action))return;event.preventDefault();
  try{if(action==='import-open'){S.importDraft=await api('/api/imports/'+el.dataset.id);S.view='imports';render();}
    if(action==='import-preview'){importPreview();$('#import-error').textContent='';}
    if(action==='import-submit'){el.disabled=true;const data=S.importDraft.preview;if(!data||JSON.stringify(JSON.parse($('#import-json').value))!==JSON.stringify(data))throw Error('JSON wurde geändert. Bitte Korrekturen erneut prüfen.');const mapping={};data.personen.forEach((p,i)=>{const choice=$(`[data-import-choice="${i}"]`).value;if(choice==='existing'){const value=$(`[data-import-existing="${i}"]`).value;const match=S.archive.personen.find(per=>`${per.anzeigename} · * ${datum(per,'geburt')} · ${per.id}`===value);if(!match)throw Error('Bestehende Person für '+p.anzeigename+' aus der Suchliste auswählen.');mapping[p.id]=match.id;}else mapping[p.id]=choice;});await post('/api/imports/'+S.importDraft.id+'/submit',{data,mapping});S.importDraft=null;await reload();S.view='review';render();toast('Linie eingereicht. Sie wartet auf Admin-Freigabe.');}
  }catch(error){const target=$('#import-error');if(target)target.textContent=error.message;else toast(error.message);}finally{el.disabled=false;}
});
document.addEventListener('submit',async event=>{
  const f=event.target;if(f.id!=='import-upload-form')return;event.preventDefault();const button=f.querySelector('button');button.disabled=true;
  try{const file=f.elements.file.files[0];if(!file)throw Error('Datei wählen.');if(file.size>S.maxUpload)throw Error('Datei zu groß. Bitte aufteilen.');const visual=/\.(pdf|png|jpe?g)$/i.test(file.name);if(visual&&!f.elements.ocr?.checked)throw Error('PDF-/Bilderkennung: Übertragung bestätigen oder JSON/GEDCOM wählen.');$('#form-error').textContent=visual?'Dokument wird erkannt. Das kann bis zu zwei Minuten dauern …':'Datei wird eingelesen …';S.importDraft=await api('/api/imports',{method:'POST',headers:{'x-title':encodeURIComponent(f.elements.title.value),'x-filename':encodeURIComponent(file.name),'x-ocr-consent':f.elements.ocr?.checked?'yes':'no'},body:file});render();importPreview();}
  catch(error){const target=f.querySelector('#form-error');if(target)target.textContent=error.message;}finally{button.disabled=false;}
});

function versionButton(){return `<button type="button" class="version-button" data-action="patch-history" aria-label="Version ${esc(APP_VERSION)} und Patch-Historie anzeigen">v${esc(APP_VERSION)} <span>· Was ist neu?</span></button>`;}
function releaseHistoryContent(){return `<header class="release-header"><div><div class="eyebrow">Ahnenarchiv · v${esc(APP_VERSION)}</div><h2 id="release-history-title">Was ist neu?</h2></div><button type="button" data-close-release aria-label="Patch-Historie schließen" autofocus>✕</button></header><div class="release-list">${RELEASES.map((release,i)=>`<section class="release-entry"><div class="release-meta"><strong>v${esc(release.version)}</strong>${i===0?'<span class="badge">Aktuelle Version</span>':''}<time datetime="${esc(release.date)}">${esc(release.date.split('-').reverse().join('.'))}</time></div><h3>${esc(release.title)}</h3><ul>${release.changes.map(change=>`<li>${esc(change)}</li>`).join('')}</ul></section>`).join('')}<p class="small muted">Die bisherigen Entwicklungsstände wurden mit dieser Historie rückwirkend nummeriert.</p></div>`;}
function openReleaseHistory(trigger){
  document.querySelector('#release-history')?.close();
  const dialog=document.createElement('dialog');dialog.id='release-history';dialog.className='release-dialog';dialog.setAttribute('aria-labelledby','release-history-title');dialog.innerHTML=releaseHistoryContent();
  const previousOverflow=document.body.style.overflow;
  dialog.querySelector('[data-close-release]').addEventListener('click',()=>dialog.close());
  dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
  dialog.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;dialog.remove();if(trigger?.isConnected)trigger.focus();},{once:true});
  document.body.append(dialog);dialog.showModal();document.body.style.overflow='hidden';
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action="patch-history"]');if(button){event.preventDefault();openReleaseHistory(button);}});

function portraitFixReview(p){return `<div class="portrait-fix-grid">${p.payload.summary.map(row=>`<section class="card"><h3>${esc(row.name)}</h3><p class="small muted">Originalseite ${esc(row.page)}</p><div class="review-row"><div class="before"><small>Bisher zugeordnet</small><a href="/api/media/${esc(row.old)}" data-image-popup><img class="portrait-fix-image" src="/api/media/${esc(row.old)}" alt="Bisheriges Bild von ${esc(row.name)}"></a></div><div class="after"><small>Richtige Zuordnung</small><a href="/api/media/${esc(row.new)}" data-image-popup><img class="portrait-fix-image" src="/api/media/${esc(row.new)}" alt="Korrigiertes Bild von ${esc(row.name)}"></a></div></div></section>`).join('')}</div><p class="small muted">Die Freigabe korrigiert alle drei Personen und Bildzuordnungen gemeinsam.</p>`;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="portrait-fix"]');if(!button)return;event.preventDefault();button.disabled=true;try{const result=await post('/api/corrections/portraits',{});if(result.already_correct){toast('Die Porträtzuordnungen sind bereits korrekt.');return;}await reload();S.view='review';render();toast('Porträtkorrektur angelegt. Bilder prüfen und freigeben.');}catch(error){toast(error.message);}finally{button.disabled=false;}});

function parenthoodConfirmed(r){if(r.belegstatus==='ungeklaert')return false;return r.belegt===true||r.biologisch_bestaetigt===true||(r.status==='freigegeben'&&['adoptiv','pflege','stief'].includes(r.elternschaft_typ));}
function familyConfirmationReview(p){return `<p>Diese Eltern-Kind-Verbindungen werden als belegt gekennzeichnet:</p><ul>${p.payload.summary.map(row=>`<li>${esc(row.parent)} → ${esc(row.child)}</li>`).join('')}</ul><p class="small muted">Danach erscheinen die Linien durchgezogen. Die Art der Elternschaft und die übrigen Verbindungen bleiben erhalten.</p>`;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="family-confirmation"]');if(!button)return;event.preventDefault();button.disabled=true;try{const result=await post('/api/corrections/family-confirmation',{});if(result.already_correct){toast('Die vier Familienverbindungen sind bereits bestätigt.');return;}await reload();S.view='review';render();toast('Bestätigung angelegt. In der Prüfliste prüfen und freigeben.');}catch(error){toast(error.message);}finally{button.disabled=false;}});

function connectionLinks(p,ids,partners=false){return ids.map(id=>{
 const records=partners?[...S.archive.beziehungen.filter(r=>r.typ==='partner'&&[r.von_person_id,r.zu_person_id].includes(p.id)&&[r.von_person_id,r.zu_person_id].includes(id)),...S.archive.familien.filter(f=>f.partner_person_ids.includes(p.id)&&f.partner_person_ids.includes(id))]:S.archive.beziehungen.filter(r=>r.typ==='eltern_kind'&&((r.von_person_id===p.id&&r.zu_person_id===id)||(r.zu_person_id===p.id&&r.von_person_id===id)));
 return `<div class="connection-row">${links([id])}${records.map(r=>`<div class="small muted">${parenthoodConfirmed(r)?'Belegt':r.belegstatus==='ungeklaert'?'Ausdrücklich ungeklärt':'Noch nicht bestätigt'}${connectionConfirmField(r)}</div>`).join('')}</div>`;
 }).join('')||'<span class="muted small">Noch nicht erfasst</span>';}
function connectionReview(p){return `<p>${p.payload.summary.length} Verbindung(en) zur Prüfung:</p><ul>${p.payload.summary.map(r=>`<li>${esc(r.label)}: ${esc(r.before)} → <strong>${r.after==='bestaetigt'?'Belegt':'Ungeklärt'}</strong></li>`).join('')}</ul><p class="small muted">Namen und Art der Elternschaft werden dabei nicht verändert.</p>`;}
function openConnectionStatus(id,trigger){const r=[...S.archive.beziehungen,...S.archive.familien].find(r=>r.id===id);if(!r)return;const dialog=document.createElement('dialog');dialog.className='release-dialog';dialog.setAttribute('aria-label','Belegstatus prüfen');dialog.innerHTML=`<h2>Belegstatus prüfen</h2><p>Bestätige die Verbindung unabhängig vom Namen oder der biologischen Einordnung. Erst eine Admin-Freigabe ändert den Bestand.</p><form id="connection-status-form"><label>Verbindung</label><select name="belegstatus"><option value="bestaetigt">Belegt – durchgezogene Linie</option><option value="ungeklaert" ${r.belegstatus==='ungeklaert'?'selected':''}>Ungeklärt – gestrichelte Linie</option></select><label>Quelle / Begründung</label><textarea name="source" required maxlength="20000" placeholder="Z. B. Stammbaumvorlage Seite … oder Geburtsurkunde …">${esc((r.quellen_verweise||[]).map(q=>'Vorlage, Seite '+q.seite).join('; '))}</textarea><p id="form-error" class="error"></p><button class="primary" type="submit">Zur Prüfung einreichen</button> <button type="button" data-close-status>Schließen</button></form>`;
 dialog.querySelector('[data-close-status]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();if(trigger?.isConnected)trigger.focus();},{once:true});dialog.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button.primary');button.disabled=true;try{await post('/api/connections/'+encodeURIComponent(id)+'/status',{...b,base_version:r.version});dialog.close();const position={x:window.scrollX,y:window.scrollY};await reload();render();window.scrollTo(position.x,position.y);toast('Eingereicht – wartet auf Admin-Freigabe.');}catch(err){f.querySelector('#form-error').textContent=err.message;}finally{button.disabled=false;}});document.body.append(dialog);dialog.showModal();}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="connection-status"],[data-action="template-confirmation"]');if(!button)return;event.preventDefault();if(button.dataset.action==='connection-status'){openConnectionStatus(button.dataset.id,button);return;}button.disabled=true;try{const result=await post('/api/corrections/template-confirmation',{});if(result.already_correct){toast('Keine ungeprüften eindeutigen Vorlagenverbindungen übrig.');return;}await reload();S.view='review';render();toast('Vorlagenverbindungen angelegt. Liste prüfen und freigeben.');}catch(err){toast(err.message);}finally{button.disabled=false;}});

function connectionConfirmField(r){if(S.share||S.desktop)return '';const pending=S.archive.connection_pending_ids?.includes(r.id)||S.proposals.some(p=>p.kind==='relationship_status'&&p.target===r.id&&p.status==='pending');if(pending)return ` · <button class="connection-pending" disabled aria-label="Bestätigung wartet auf Freigabe">Wartet auf Freigabe</button>`;if(parenthoodConfirmed(r))return '';return ` · <button data-action="connection-status" data-id="${esc(r.id)}">Belegstatus prüfen</button>`;}

function startEvidenceWatch(){if(S.evidenceWatching)return;S.evidenceWatching=true;async function tick(){try{if(S.user&&!S.share&&!document.hidden&&S.view==='detail'&&S.archive?.connection_pending_ids?.length&&!document.querySelector('dialog[open]')){const selected=S.selected,before=JSON.stringify(S.archive.connection_pending_ids);await reload();if(S.view==='detail'&&S.selected===selected&&!document.querySelector('dialog[open]')&&before!==JSON.stringify(S.archive.connection_pending_ids)){const position={x:window.scrollX,y:window.scrollY};render();window.scrollTo(position.x,position.y);}}}catch(error){/* Offline: keep current page; retry later. */}finally{setTimeout(tick,15000);}}setTimeout(tick,15000);}

function cleanCredentialUrl(){if(typeof location.href!=='string'||typeof history==='undefined')return;const url=new URL(location.href);let changed=false;for(const key of [...url.searchParams.keys()])if(/^(email|e-mail|mail|username|user|login|password|passwort|passwd|pwd|key|setup_key|repeat|new_password|current_password)$/i.test(key)){url.searchParams.delete(key);changed=true;}if(url.username||url.password){url.username='';url.password='';changed=true;}if(url.hash&&!url.hash.startsWith('#share=')&&/(password|passwort|email|passwd|pwd|setup_key)=/i.test(url.hash)){url.hash='';changed=true;}if(changed)history.replaceState(null,'',url.pathname+url.search+url.hash);}
function accountView(){return `<h1>Mein Konto</h1><section class="card"><p>Angemeldet als ${esc(S.user?.name)} · ${esc(S.user?.email)}</p><h2>Passwort ändern</h2><p>Nach dem Wechsel werden alle bisherigen Anmeldungen dieses Kontos beendet, auch auf anderen Geräten.</p><form id="password-form" method="post" action="/api/account/password"><label>Aktuelles Passwort</label><input name="current_password" type="password" autocomplete="current-password" required maxlength="1024"><label>Neues Passwort</label><input name="new_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"><label>Neues Passwort wiederholen</label><input name="repeat" type="password" autocomplete="new-password" required minlength="12" maxlength="256"><p id="form-error" class="error"></p><button class="primary" type="submit">Passwort ändern & alle Sitzungen abmelden</button></form></section>`;}


function familyBranchPaths(edges,pos){
 const byChild=new Map();for(const r of edges){if(!byChild.has(r.zu_person_id))byChild.set(r.zu_person_id,[]);byChild.get(r.zu_person_id).push(r);}
 const families=new Map();for(const [child,rels] of byChild){rels.sort((a,b)=>a.von_person_id.localeCompare(b.von_person_id));const key=JSON.stringify([pos.get(child).y,rels.map(r=>[r.von_person_id,parenthoodConfirmed(r)])]);if(!families.has(key))families.set(key,{parents:rels.map(r=>r.von_person_id),children:[],rels:[],states:rels.map(parenthoodConfirmed)});const f=families.get(key);f.children.push(child);f.rels.push(...rels);}
 let lane=0;const path=(d,klass,dashed=false)=>`<path class="${klass}" d="${d}" stroke="#526e5a" stroke-width="1.6" stroke-linejoin="round" fill="none" ${dashed?'stroke-dasharray="5 4"':''}/>`;
 return [...families.values()].map((f,index)=>{const parents=f.parents.map(id=>pos.get(id)),children=f.children.map(id=>pos.get(id)),childY=children[0].y,parentY=Math.max(...parents.map(p=>p.y+110)),joinY=parentY+20,busY=childY-24-(index%3)*8,center=parents.reduce((sum,p)=>sum+p.x+98,0)/parents.length,childXs=children.map(p=>p.x+98),target=childXs.reduce((a,b)=>a+b,0)/childXs.length,uncertain=f.states.some(v=>!v);let html='';
 if(parents.every(p=>p.y===parents[0].y)){
  parents.forEach((p,i)=>html+=path(`M${p.x+98},${p.y+110} V${joinY} H${center}`,'parent-connect',!f.states[i]));
  if(childY-parents[0].y>190){const slot=lane++;html+=path(`M${center},${joinY} V${joinY+18} H${16+slot*8} V${busY} H${target}`,'family-trunk',uncertain);}
  else html+=path(`M${center},${joinY} V${busY} H${target}`,'family-trunk',uncertain);
 }else{parents.forEach((p,i)=>{const slot=lane++;html+=path(`M${p.x+98},${p.y+110} V${p.y+130} H${16+slot*8} V${busY} H${target}`,'parent-connect',!f.states[i]);});}
 html+=path(`M${Math.min(...childXs)},${busY} H${Math.max(...childXs)}`,'family-bus',uncertain);
 children.forEach((p,i)=>{html+=`<path class="child-branch" data-to="${esc(f.children[i])}" d="M${p.x+98},${busY} V${childY}" stroke="#526e5a" stroke-width="1.6" fill="none" ${uncertain?'stroke-dasharray="5 4"':''}/>`;});
 html+=`<circle cx="${target}" cy="${busY}" r="2.5" fill="#526e5a"/>`;
 return `<g class="family-branch" data-parents="${esc(f.parents.join(','))}" data-children="${esc(f.children.join(','))}" data-relationships="${esc(f.rels.map(r=>r.id).join(','))}">${html}</g>`;
 }).join('');
}

function userAdminForms(){const common=`<label>Name</label><input name="name" required maxlength="200"><label>E-Mail-Adresse</label><input name="email" type="email" required maxlength="254"><label>Rolle</label><select name="role"><option value="member">Mitforschender</option><option value="admin">Administrator</option></select>`;return `<section class="card"><h2>Per E-Mail einladen</h2><p>Der Empfänger setzt sein Passwort selbst. Der Link gilt sieben Tage; das Konto ist danach sofort freigegeben.</p><form id="admin-invite-form" method="post" action="/api/invitations">${common}<p class="error" id="form-error"></p><button class="primary" type="submit">Einladung senden</button></form><div id="invite-result" role="status"></div><h3>Einladungen</h3><div id="invitation-list">Wird geladen …</div></section><section class="card"><h2>Benutzer direkt anlegen</h2><form id="admin-user-form" method="post" action="/api/users">${common}<label>Startpasswort (mindestens 12 Zeichen)</label><input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"><p class="small muted">Das Konto ist sofort aktiv. Passwort persönlich weitergeben; der Nutzer kann es unter Mein Konto ändern.</p><p class="error" id="form-error"></p><button class="primary" type="submit">Benutzer anlegen</button></form></section>`;}
async function loadInvitations(){const target=$('#invitation-list');if(!target)return;try{const rows=await api('/api/invitations');target.innerHTML=rows.map(i=>{const pending=i.status==='pending'&&Number(i.expires)*1000>Date.now();const status=i.status==='accepted'?'Angenommen':i.status==='revoked'?'Widerrufen':pending?'Offen':'Abgelaufen';return `<div class="source"><strong>${esc(i.name)}</strong> · ${esc(i.email)} · ${i.role==='admin'?'Administrator':'Mitforschender'}<p>${status} · gültig bis ${esc(new Date(Number(i.expires)*1000).toLocaleString('de-DE'))} · ${i.delivery==='accepted'?'E-Mail an Mailserver übergeben':'E-Mail nicht versendet'}</p>${pending?`<button data-action="invite-revoke" data-id="${esc(i.id)}">Einladung widerrufen</button>`:''}</div>`;}).join('')||'<p class="muted">Noch keine Einladungen.</p>';}catch(e){target.textContent=e.message;}}
async function invitationView(t){try{const i=await post('/api/invitations/preview',{token:t});$('#app').innerHTML=`<div class="login-form"><h1>Willkommen im Ahnenarchiv</h1><p>Einladung für <strong>${esc(i.name)}</strong> · ${esc(i.email)}</p><p>Rolle: ${i.role==='admin'?'Administrator':'Mitforschender'}</p><form id="accept-invite-form" method="post" action="/api/invitations/accept"><input name="token" type="hidden" value="${esc(t)}"><label>Dein neues Passwort</label><input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required><label>Passwort wiederholen</label><input name="repeat" type="password" autocomplete="new-password" minlength="12" maxlength="256" required><p class="error" id="form-error"></p><button class="primary" type="submit">Konto einrichten</button></form></div>`;}catch(e){login();toast(e.message);}}
document.addEventListener('submit',async e=>{const f=e.target;if(!['admin-user-form','admin-invite-form','accept-invite-form'].includes(f.id))return;e.preventDefault();const button=f.querySelector('button');button.disabled=true;f.querySelector('#form-error').textContent='';try{const b=Object.fromEntries(new FormData(f));if(f.id==='accept-invite-form'){if(b.password!==b.repeat)throw Error('Passwörter unterscheiden sich.');const result=await post('/api/invitations/accept',b);f.reset();login();toast(result.message);}else if(f.id==='admin-user-form'){await post('/api/users',b);f.reset();await loadUsers();await loadInvitations();toast('Benutzer angelegt und freigegeben.');}else{const result=await post('/api/invitations',b);f.reset();$('#invite-result').innerHTML=`<p class="${result.mail_accepted?'success':'error'}">${esc(result.message)}</p><label>Einladungslink (nur jetzt sichtbar)</label><input value="${esc(result.url)}" readonly aria-label="Einladungslink"><p class="small muted">Dieser Link gewährt Zugang. Nur an den eingeladenen Empfänger weitergeben.</p>`;await loadInvitations();}}catch(err){f.querySelector('#form-error').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action="invite-revoke"]');if(!button)return;button.disabled=true;try{await post('/api/invitations/'+button.dataset.id+'/revoke',{});await loadInvitations();toast('Einladung widerrufen.');}catch(err){button.disabled=false;toast(err.message);}});

boot();
